mapper.sql:
SELECT afs.ID AS id, afs.create_user_id AS createUserId, afs.create_user_name AS createUserName, afs.create_time AS createTime, afs.update_user_id AS updateUserId, afs.update_user_name AS updateUserName, afs.update_time AS updateTime, afs.VERSION AS version, afs.is_deleted AS isDeleted, afs.code AS code, afs.status AS status, afs.bill_date AS billDate, afs.approve_status AS approveStatus, CASE WHEN afs.approve_status = 'approve' THEN afs.approve_time ELSE null END AS approveTime, afs.approve_user_id AS approveUserId, afs.approve_user_name AS approveUserName, afs.thrid_user_id AS thridUserId, afs.thrid_type AS thridType, afs.platform_code AS platformCode, afs.dict_platform AS dictPlatform, afs.buy_date AS buyDate, afs.address AS address, afs.fault_desc AS faultDesc, afs.repair_invoice_code AS repairInvoiceCode, afs.total_price AS totalPrice, afs.total_repair_amount AS totalRepairAmount, afs.invalid_status AS invalidStatus, afs.invalid_remark AS invalidRemark, afs.invalid_time AS invalidTime, afs.remark AS remark, afs.csr_remark AS csrRemark, afs.rma_remark AS rmaRemark, afsd.id AS detailId, afsd.main_id AS mainId, afsd.price AS price, afsd.sku_id AS skuId, afsd.sku_no AS skuNo, afsd.product_name AS productName, afsd.sku_qty AS skuQty, afsd.price AS price, afsd.detail_desc AS detailDesc, afs.username AS thridUserName, tui.nick_name AS nickName, afs.phone_number AS phoneNumber, r.track_no as returnTrackNo, o.track_no as outboundTrackNo FROM after_sale AS afs LEFT JOIN after_sale_detail AS afsd ON afs.ID = afsd.main_id AND afsd.is_deleted = FALSE LEFT JOIN thrid_user_info AS tui ON afs.thrid_user_id = tui.ID AND tui.is_deleted = FALSE LEFT JOIN after_sale_progress AS r ON r.main_id = afs.ID AND r.node = 'toBeReturned' AND r.is_deleted = FALSE LEFT JOIN after_sale_progress AS o ON o.main_id = afs.ID AND o.node IN ( 'toBeShipped', 'terminated' ) AND o.is_deleted = FALSE where ${params.sqlMap.default} AND afs.is_deleted = false
and afs.id in
#{id}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
afs.create_time DESC

mapper.select:
SELECT afs.approve_status AS tabFlag, count(1) AS count FROM after_sale as afs WHERE afs.is_deleted=FALSE and afs.approve_status !='waitSubmit'
${params.permissionSql}
GROUP BY afs.approve_status

select afs.id, afs.status, afsp.id as detailId, afsp.node , afsp.node_time as nodeTimeLd , afsp.track_no , afsp.remark , afsp.index from after_sale afs left join after_sale_progress afsp on afs.id = afsp.main_id and afsp.is_deleted = FALSE where afs.is_deleted = false
and afs.code = #{params.code}
and afs.thrid_user_id = #{params.thridUserId}
order by index

select afs.id, afs.code, afs.status, afs.update_time, afs.remark from after_sale afs where afs.is_deleted = false
and afs.thrid_user_id = #{params.thridUserId}
order by afs.create_time desc
